bodyHtml:
{#
	The newest of her listings that is For sale or Coming soon and not Private.
	data is the subscriber; data.lang picks the language.
#}
{% set es = data.lang|default('') == 'es' %}
{% set pick = cms.collection.objects('listings')|filter(x => x.mine and not x.private|default(false) and x.status in ['for-sale', 'coming-soon'])|sort((a, b) => b.listedOn|default('') <=> a.listedOn|default(''))|first %}
{% set l = cms.collection.object('listings', pick.id) %}
{% set info = cms.collection.object('info', 'info') %}
{% set town = cms.collection.object('neighborhoods', l.town).name|default(l.town) %}
{% set link = cms.builder.canonicalUrl(es ? 'listing-es' : 'listing', {id: l.id}) %}
{% set base = cms.builder.canonicalUrl('home')|trim('/', 'right') %}
{% set about = (l.description[es ? 'es' : 'en_US']|default('') ?: l.description.en_US|default(''))|striptags|split("\n")|first %}
<div style="max-width:600px;margin:0 auto;font-family:Georgia,serif;color:#3b2f33">
	<p style="font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:#8a4b56">{{ es ? 'Nueva en el mercado' : 'Just listed' }}</p>
	<h1 style="font-weight:400;font-size:28px;margin:0 0 4px">{{ l.address|e }}</h1>
	<p style="margin:0 0 16px;color:#6b5a5e">{{ town|e }}, CA {{ l.zip|e }}</p>
	{% if l.gallery|default([]) is not empty %}
		<a href="{{ link }}"><img src="{{ base }}/imageworks/listings/{{ l.id }}/gallery/first?w=1200&h=800&fit=crop" width="600" alt="{{ l.address|e }}" style="display:block;width:100%;height:auto;border-radius:300px 300px 0 0"></a>
	{% endif %}
	<p style="font-size:24px;margin:20px 0 4px">${{ l.price|number_format(0, '.', ',') }}</p>
	<p style="margin:0 0 16px;color:#6b5a5e">{{ l.beds }} {{ es ? 'hab.' : 'bd' }} · {{ l.baths }} {{ es ? 'baños' : 'ba' }} · {{ l.sqft|number_format(0, '.', ',') }} {{ es ? 'pies²' : 'sq ft' }}</p>
	{% if about %}<p style="line-height:1.6">{{ about|e }}</p>{% endif %}
	<p style="margin:24px 0"><a href="{{ link }}" style="background:#8a4b56;color:#fff;padding:12px 24px;text-decoration:none;letter-spacing:.08em;text-transform:uppercase;font-family:Arial,sans-serif;font-size:13px">{{ es ? 'Ver la casa' : 'See the home' }}</a></p>
	<p>{{ es ? 'Acaba de salir al mercado, y usted es de los primeros en saberlo. Si quiere verla, responda a este correo.' : 'It just came on the market, and you are among the first to hear. If you would like to see it, reply to this email.' }}</p>
	<p>{{ info.signature|default(info.name)|e }}<br><span style="color:#6b5a5e">{{ info.name|e }} · {{ info.phone|e }}{% if info.license %} · {{ info.license|e }}{% endif %}</span></p>
	<p style="font-size:12px;color:#6b5a5e;border-top:1px solid #ead8da;padding-top:12px;margin-top:32px">
		{% if es %}Recibe este correo porque se suscribió a las casas nuevas de {{ info.name|e }}. <a href="{{ unsubscribeUrl }}">Cancelar la suscripción</a>.
		{% else %}You are receiving this because you joined {{ info.name|e }}'s Just-listed emails. <a href="{{ unsubscribeUrl }}">Unsubscribe</a>.{% endif %}
	</p>
</div>
